patch_result.patch:
--- a/valid.c
+++ b/valid.c
@@ -2734,6 +2734,7 @@
 int
 xmlRemoveID(xmlDocPtr doc, xmlAttrPtr attr) {
     xmlIDTablePtr table;
+    xmlChar *idVal;

     if (doc == NULL) return(-1);
     if ((attr == NULL) || (attr->id == NULL)) return(-1);
@@ -2742,9 +2743,16 @@
     if (table == NULL)
         return(-1);

-    if (xmlHashRemoveEntry(table, attr->id->value, xmlFreeIDTableEntry) < 0)
+    idVal = xmlStrdup(attr->id->value);
+    if (idVal == NULL)
         return(-1);

+    if (xmlHashRemoveEntry(table, idVal, xmlFreeIDTableEntry) < 0) {
+        xmlFree(idVal);
+        return(-1);
+    }
+    xmlFree(idVal);
+
     attr->atype = 0;
     attr->id = NULL;

args:
@@ -2735,6 +2735,7 @@
 xmlRemoveID(xmlDocPtr doc, xmlAttrPtr attr) {
     xmlIDTablePtr table;
+    xmlChar *idVal;

     if (doc == NULL) return(-1);
     if ((attr == NULL) || (attr->id == NULL)) return(-1);
@@ -2742,7 +2743,13 @@ xmlRemoveID(xmlDocPtr doc, xmlAttrPtr attr) {
     if (table == NULL)
         return(-1);

-    if (xmlHashRemoveEntry(table, attr->id->value, xmlFreeIDTableEntry) < 0)
+    idVal = xmlStrdup(attr->id->value);
+    if (idVal == NULL)
+        return(-1);
+
+    if (xmlHashRemoveEntry(table, idVal, xmlFreeIDTableEntry) < 0) {
+        xmlFree(idVal);
         return(-1);
+    }
+    xmlFree(idVal);

     attr->atype = 0;
     attr->id = NULL;
